insert into public.lessons (id,title,korean_title,category,level,duration_minutes,objectives,expressions,scenario,sort_order) values
('a1000000-0000-4000-8000-000000000001','Meeting Someone','처음 만났어요','Everyday','Beginner','4','["Greet someone politely","Introduce yourself and ask their name"]','[{"korean":"안녕하세요.","english":"Hello."},{"korean":"저는 민수예요.","english":"I’m Minsu."},{"korean":"이름이 뭐예요?","english":"What’s your name?"}]','Panda meets the learner for the first time. Introduce yourself and ask the learner their name. Use beginner-friendly polite Korean.','1'),
('a1000000-0000-4000-8000-000000000002','Ordering Coffee','카페에서 주문해요','Everyday','Beginner','4','["Choose a drink","Order politely"]','[{"korean":"아이스 아메리카노 하나 주세요.","english":"An iced Americano, please."},{"korean":"따뜻한 커피 주세요.","english":"A warm coffee, please."},{"korean":"감사합니다.","english":"Thank you."}]','Panda is a café employee ready to take the learner’s order. Help them order one drink politely using beginner-friendly Korean.','2'),
('a1000000-0000-4000-8000-000000000003','Talking About Yourself','어디에서 왔어요?','People','Beginner','4','["Ask where someone is from","Say where you live"]','[{"korean":"어디에서 왔어요?","english":"Where are you from?"},{"korean":"저는 미국에서 왔어요.","english":"I’m from the United States."},{"korean":"저는 서울에 살아요.","english":"I live in Seoul."}]','Panda meets the learner at a social gathering and asks where they are from. Ask where the learner lives too.','3'),
('a1000000-0000-4000-8000-000000000004','Talking About Food','음식을 좋아해요','Food','Beginner','4','["Name Korean foods","Say what you like and ask about preferences"]','[{"korean":"저는 김치를 좋아해요.","english":"I like kimchi."},{"korean":"비빔밥이 맛있어요.","english":"Bibimbap is delicious."},{"korean":"매운 음식을 좋아해요?","english":"Do you like spicy food?"}]','Panda chats with the learner about favorite Korean foods. Ask what the learner likes and share a favorite.','4'),
('a1000000-0000-4000-8000-000000000005','Making Plans','같이 만날까요?','Everyday','Beginner','4','["Ask about someone’s availability","Suggest doing something together"]','[{"korean":"내일 시간 있어요?","english":"Are you free tomorrow?"},{"korean":"주말에 뭐 해요?","english":"What are you doing this weekend?"},{"korean":"같이 커피 마실까요?","english":"Shall we have coffee together?"}]','Panda is a friend checking the learner’s availability for the weekend. Make a simple plan together.','5'),
('a1000000-0000-4000-8000-000000000006','At the corner shop','편의점에서','Everyday','Beginner','5','["Ask for an item","Pay and request a bag"]','[{"korean":"봉투 주세요.","english":"A bag, please."},{"korean":"카드로 계산할게요.","english":"I will pay by card."}]','You are a friendly convenience-store cashier. Help the learner find a snack and pay. Ask one simple question at a time.','6'),
('a1000000-0000-4000-8000-000000000007','A thoughtful purchase','쇼핑해요','Everyday','Beginner','5','["Ask a price and a size","Politely decline an item"]','[{"korean":"이거 얼마예요?","english":"How much is this?"},{"korean":"다른 사이즈가 있어요?","english":"Do you have another size?"}]','You are a shop assistant selling a sweater. Ask about color and size, give a fictional price clearly within the roleplay and let the learner decide.','7'),
('a1000000-0000-4000-8000-000000000008','Make a new friend','친구가 돼요','People','Beginner','5','["Talk about a hobby","Invite someone to meet again"]','[{"korean":"취미가 뭐예요?","english":"What is your hobby?"},{"korean":"다음에 같이 가요.","english":"Let us go together next time."}]','You are a new acquaintance at a language exchange. Discuss hobbies in polite 해요체 and suggest a simple future activity.','8'),
('a1000000-0000-4000-8000-000000000009','Your first campus day','캠퍼스 첫날','Campus','Intermediate','5','["Ask about campus facilities","Clarify a class location"]','[{"korean":"학생증은 어디에서 만들어요?","english":"Where do I get a student ID?"},{"korean":"강의실이 바뀌었나요?","english":"Has the classroom changed?"}]','You are a student mentor helping a new international student find a classroom and the library. Use invented campus details only for this roleplay.','9'),
('a1000000-0000-4000-8000-000000000010','Talk to your professor','교수님과 상담해요','Campus','Intermediate','5','["Explain a study difficulty respectfully","Request an appointment"]','[{"korean":"상담 시간을 예약하고 싶습니다.","english":"I would like to book a consultation."},{"korean":"이 부분을 다시 설명해 주실 수 있나요?","english":"Could you explain this part again?"}]','You are a university professor in office hours. Invite the learner to explain a study difficulty and help them make a respectful request.','10'),
('a1000000-0000-4000-8000-000000000011','A room of your own','방을 구해요','Everyday','Intermediate','5','["Ask about rent and included costs","Arrange a viewing"]','[{"korean":"관리비가 포함되어 있나요?","english":"Is the maintenance fee included?"},{"korean":"방을 보러 가도 될까요?","english":"May I come to see the room?"}]','You are a fictional rental agent. Practice questions about rent, deposit and facilities. This is language practice, not legal or financial advice.','11'),
('a1000000-0000-4000-8000-000000000012','Feeling under the weather','병원 접수','Everyday','Intermediate','5','["Describe basic symptoms","Understand reception questions"]','[{"korean":"어제부터 목이 아파요.","english":"My throat has hurt since yesterday."},{"korean":"예약하지 않았는데 진료받을 수 있나요?","english":"Can I be seen without an appointment?"}]','You are a clinic receptionist, not a doctor. Practice check-in and describing symptoms. Do not diagnose or recommend treatment; direct real urgent symptoms to professional help.','12'),
('a1000000-0000-4000-8000-000000000013','A weekend together','주말 약속','People','Intermediate','5','["Suggest a time and activity","Reschedule politely"]','[{"korean":"토요일 오후에 시간 있어요?","english":"Are you free on Saturday afternoon?"},{"korean":"다음 주로 미뤄도 될까요?","english":"Could we move it to next week?"}]','You are a friend planning a weekend outing. Negotiate a time, activity and a polite change of plans. Maintain polite language unless the learner explicitly asks to practice casual speech.','13'),
('a1000000-0000-4000-8000-000000000014','A call to the hotel','숙소에 전화해요','Travel','Intermediate','5','["Confirm a reservation","Request a check-in detail"]','[{"korean":"예약을 확인하고 싶어요.","english":"I would like to confirm my reservation."},{"korean":"체크인은 몇 시부터 가능한가요?","english":"What time does check-in begin?"}]','You are a hotel receptionist. Practice confirming an invented reservation and explaining check-in details without asking for real payment or identity information.','14'),
('a1000000-0000-4000-8000-000000000015','Your first team meeting','첫 팀 회의','Work','Intermediate','5','["Give a brief work update","Ask a colleague to clarify"]','[{"korean":"진행 상황을 공유하겠습니다.","english":"I will share a progress update."},{"korean":"마감일을 다시 확인해도 될까요?","english":"May I confirm the deadline again?"}]','You are a colleague in a small team meeting. Ask for a brief project update and discuss an invented deadline. Encourage professional Korean.','15'),
('a1000000-0000-4000-8000-000000000016','A small misunderstanding','오해를 풀어요','People','Intermediate','5','["Explain your intended meaning","Apologize and clarify politely"]','[{"korean":"제 뜻은 그게 아니었어요.","english":"That was not what I meant."},{"korean":"제가 잘못 이해한 것 같아요.","english":"I think I misunderstood."}]','You are a friend who misunderstood a meeting arrangement. Give the learner a calm opportunity to clarify and repair the conversation.','16'),
('a1000000-0000-4000-8000-000000000017','Tell your work story','면접 연습','Work','Advanced','8','["Describe relevant experience clearly","Support an answer with an example"]','[{"korean":"제 경험을 바탕으로 말씀드리면…","english":"Speaking from my experience…"},{"korean":"이 문제를 해결하기 위해…","english":"In order to solve this problem…"}]','You are a fictional interviewer. Ask about a project, a challenge and what the learner learned. Give language feedback, not promises of employment.','17'),
('a1000000-0000-4000-8000-000000000018','A campus proposal','학생회에 제안해요','Campus','Advanced','8','["Make and support a proposal","Respond to a counterargument"]','[{"korean":"이 제도의 개선이 필요하다고 생각합니다.","english":"I think this system needs improvement."},{"korean":"그 우려는 이해하지만…","english":"I understand that concern, but…"}]','You are a student-council member discussing improvements to a campus study space. Ask the learner to propose a change and answer one reasonable objection.','18'),
('a1000000-0000-4000-8000-000000000019','Explain a changing trend','변화를 설명해요','TOPIK','Advanced','8','["Describe a trend using comparisons","Separate observation from explanation"]','[{"korean":"이전보다 크게 증가했습니다.","english":"It increased significantly compared with before."},{"korean":"그 원인으로는…을 들 수 있습니다.","english":"One possible cause is…"}]','You are a Korean tutor practicing verbal descriptions of an invented trend: library visits rose from 100 to 150 per day. Clearly describe these as practice data, not real statistics.','19'),
('a1000000-0000-4000-8000-000000000020','An opinion with reasons','의견을 나눠요','TOPIK','Advanced','8','["Express an opinion with reasons","Acknowledge an alternative view"]','[{"korean":"제 생각에는…","english":"In my opinion…"},{"korean":"반면에 이런 의견도 있습니다.","english":"On the other hand, there is also this view."}]','You are a discussion partner considering whether students should do group projects. Ask for a position, supporting reason and acknowledgement of another view. This is conversation practice, not an official TOPIK score.','20')
